      "Annual lease 08/15/2027–07/31/2028. Installment count and per-person versus per-unit price basis not explicit. Prices are starting rates.",
      "Unconditional fixed recurring charges: Fetch $15 + Green $25 + Valet Trash $10 = $50 per installment. Credit $8.95 and Damage Waiver $13.50 are required only if applicable.",
      "All advertised rates exceed base by $72.45. K retains the $22.45 above the unconditional subtotal; it equals both conditional programs. Confirm applicability before treating that difference as required.",
      "D5 lower endpoints are in H and I; upper endpoints in P and Q. It is one advertised range, not two independently available room types. R and S calculate its upper subtotal and gap.",
      "Studio 396/511 sqft, 2-bed 957/981 sqft and 3-bed 1228 sqft lack plan names. Their source values are retained with descriptive placeholders, not invented plan codes.",
      "Premium bedroom and premium bath variants already use their quoted base rents. Optional desired floor/view/balcony amenities are separate, not guaranteed, and cadence is unconfirmed.",
      "Wi-Fi, cable, internet and trash included; water and electricity are usage-based extras. Explicit $10 valet trash fee is retained despite the general trash inclusion statement.",
      "Need official URL, address, photos, confirmed amenity list, pricing capture date, per-person basis, installment count, unnamed plan codes and conditional program applicability.",
      "Security deposit $100 due at lease completion; refundability not supplied. Application $99 and administration $150 are due when application completed.",
      "Known subtotals are base plus unconditional fixed recurring fees. They exclude usage-based utilities, conditional programs, optional parking/premiums and one-time payments."
